// 2\n    let address = GlobalLock(storage) else error(failed, \"clipboard text cannot be read\")\n    defer discard(GlobalUnlock(storage))\n    let wide = (u16*)address\n    var length: usize = 0\n    while length < capacity and length <= text_limit and wide[length] != 0:\n        length += 1\n    if length == capacity or length > text_limit:\n        error(failed, \"clipboard text is unterminated or exceeds the limit\")\n    with memory.heap:\n        let value = try windows_text.narrow(u16[](wide, length), failed)\n        defer free(u8[]((u8*)value.bytes.data, value.length + 1))\n        if value.length > text_limit:\n            error(failed, \"clipboard text exceeds 1 MiB\")\n        return try interop.copy_text(value)\n\nfunc win_write(text: str) -> !:\n    let owner = GetActiveWindow() else error(failed, \"clipboard writing requires an active application window\")\n    with memory.heap:\n        var terminated = try strings.Builder.create(text.length)\n        defer terminated.destroy()\n        try terminated.put(text)\n        let wide = try windows_text.wide((c.str)terminated.view(), failed)\n        defer free(wide)\n        let storage = GlobalAlloc(2, wide.length * 2) else error(failed, \"could not allocate clipboard storage\")\n        var published = false\n        defer free_unpublished(storage, &published)\n        let address = GlobalLock(storage) else error(failed, \"could not lock clipboard storage\")\n        memory.copy(u8[]((u8*)address, wide.length * 2), u8[]((u8*)wide.data, wide.length * 2), wide.length * 2)\n        discard(GlobalUnlock(storage))\n        if OpenClipboard(owner) == 0:\n            error(failed, \"the clipboard is busy\")\n        defer discard(CloseClipboard())\n        if EmptyClipboard() == 0 or SetClipboardData(unicode_text, storage) == none:\n            error(failed, \"could not publish clipboard text\")\n        published = true\n\nfunc free_unpublished(storage: void*, published: bool*):\n    if not *published:\n        discard(GlobalFree(storage))\n", 7375})}), ((lb_12sema_prelude_Prelude){.name = ((lb_str){"fonts", 5}), .text = ((lb_str){"## Native font resources and grayscale rasterization. UI typography and caches\n## belong to the UI package; this module owns only the operating-system boundary.\nimport c\nimport interop\nimport math\nimport memory\nimport platform\nimport strings\nimport thread\nimport utf8\nimport windows_text\n\npub let failed: ErrorCode = ErrorCode.package(118)\n\n## A top-down tightly packed coverage image. Copies borrow; close one owner.\npub struct Bitmap:\n    pub var pixels: u8[]\n    pub var width: u32\n    pub var height: u32\n    pub var padding: f64\n\n    pub mutating func close():\n        if self.pixels.length > 0:\n            free(self.pixels) in memory.heap\n        self = Bitmap()\n\n## An installed monospace face, in logical points. An empty family selects Menlo\n## on macOS, Consolas on Windows and the fontconfig monospace family on Linux.\n## Loading and rasterization require the UI thread. Copies borrow one native owner.\npub struct Face:\n    var native: void*\?\n    var auxiliary: void*\?\n    pub let size: f64\n    pub let advance: f64\n    pub let ascent: f64\n    pub let descent: f64\n\n    pub func init(size: f64 = 14.0, family: str = \"\") -> !:\n        try check_thread()\n        if not (size >= 8.0 and size <= 64.0):\n            error(failed, \"font size must be finite and in 8..64 points\")\n        if family.length > 255 or not utf8.valid(family.bytes):\n            error(failed, \"font family must be UTF-8 within 255 bytes\")\n        for byte in family.bytes:\n            if byte == 0:\n                error(failed, \"font family cannot contain NUL\")\n        let loaded = try load_face(size, family)\n        self.native = loaded.native\n        self.auxiliary = loaded.auxiliary\n        self.size = size\n        self.advance = loaded.advance\n        self.ascent = loaded.ascent\n        self.descent = loaded.descent\n\n    pub func measure(text: str) -> f64!:\n        if self.native == none:\n            error(failed, \"the font is closed\")\n        return (f64)(try scalar_count(text)) * self.advance\n\n    ## One scalar per monospace cell, with native glyph fallback where available.\n    ## This is code-grid text, not paragraph shaping or bidirectional layout.\n    pub func rasterize(text: str, scale: f64 = 1.0) -> Bitmap!:\n        try check_thread()\n        let width = try self.measure(text)\n        if not (scale >= 0.5 and scale <= 4.0):\n            error(failed, \"font raster scale must be finite and in 0.5..4\")\n        let columns = (usize)math.ceil(width * scale) + 4\n        let rows = (usize)math.ceil((self.ascent + self.descent) * scale) + 4\n        if columns > 16384 or rows > 1024 or columns * rows > 4194304:\n            error(failed, \"rasterized text exceeds the 4 MiB image limit\")\n        let pixels = try new u8[columns * rows] in memory.heap\n        var bitmap = Bitmap(pixels, (u32)columns, (u32)rows, 2.0 / scale)\n        errdefer bitmap.close()\n        if platform.macos:\n            try mac_raster(self, text, scale, &bitmap)\n        elif platform.windows:\n            try win_raster(self, text, scale, &bitmap)\n        elif platform.linux:\n            try linux_raster(self, text, scale, &bitmap)\n        else:\n            error(failed, \"native fonts are unavailable on this target\")\n        return bitmap\n\n    pub mutating func close():\n        if let native = self.native:\n            if platform.macos:\n                CFRelease(native)\n            elif platform.windows:\n                win_close(native, self.auxiliary)\n            elif platform.linux:\n                cairo_scaled_font_destroy(native)\n            self.native = none\n            self.auxiliary = none\n\nfunc check_thread() -> !:\n    if not thread.is_main():\n        error(interop.wrong_thread, \"font operations require the UI thread\")\n\nfunc scalar_count(text: str) -> usize!:\n    if text.length > 4096:\n        error(failed, \"a text run supports at most 4096 UTF-8 bytes\")\n    var offset: usize = 0\n    var count: usize = 0\n    while offset < text.length:\n        let decoded = utf8.decode(text.bytes, offset) else error(failed, \"text must be valid UTF-8\")\n        if (u32)decoded.scalar == 0 or (u32)decoded.scalar == 10 or (u32)decoded.scalar == 13 or (u32)decoded.scalar == 9:\n            error(failed, \"text runs cannot contain NUL, tabs or line breaks\")\n        offset += decoded.width\n        count += 1\n    if count > 1024:\n        error(failed, \"a text run supports at most 1024 scalars\")\n    return count\n\nstruct NativeFace:\n    var native: void*\?\n    var auxiliary: void*\?\n    var advance: f64\n    var ascent: f64\n    var descent: f64\n\nfunc load_face(size: f64, family: str) -> NativeFace!:\n    if platform.macos:\n        return try mac_face(size, family)\n    if platform.windows:\n        return try win_face(size, family)\n    if platform.linux:\n        return try linux_face(size, family)\n    error(failed, \"native fonts are unavailable on this target\")\n\nfunc family_bytes(text: str) -> u8[]!:\n    let bytes = try alloc u8[text.length + 1]\n    memory.copy(bytes, text.bytes, text.length)\n    bytes[text.length] = 0\n    return bytes\n## CoreText resolves installed faces and fallback glyphs. CoreGraphics writes\n## grayscale alpha at backing resolution, with LCD color fringes disabled.\nextern struct FontPoint:\n    x: f64\n    y: f64\nextern struct FontSize:\n    width: f64\n    height: f64\nextern func CFStringCreateWithBytes(allocator: void*\?, bytes: const u8*, length: i64, encoding: u32, external: bool) -> void*\?\nextern func CFRelease(object: void*)\nextern func CTFontCreateWithName(name: void*, size: f64, matrix: void*\?) -> void*\?\nextern func CTFontCreateCopyWithAttributes(font: void*, size: f64, matrix: void*\?, attributes: void*\?) -> void*\?\nextern func CTFontGetAscent(font: void*)